const path = require('path');

const PUBLIC_ROOT = path.resolve(__dirname, '..', 'public');

function resolvePublicPath(requestPath, root = PUBLIC_ROOT) {
  let decoded;
  try { decoded = decodeURIComponent(String(requestPath)); } catch { return null; }
  if (decoded.includes('\0')) return null;
  const base = path.resolve(root);
  const target = path.resolve(base, '.' + path.sep + decoded);
  const rel = path.relative(base, target);
  if (rel === '') return target;
  if (rel.startsWith('..') || path.isAbsolute(rel)) return null;
  return target;
}

module.exports = { resolvePublicPath, PUBLIC_ROOT };

