'use strict';

function parseIntParam(raw, fallback, min, max) {
  if (raw === undefined || raw === '') return { value: fallback };
  if (!/^\d+$/.test(String(raw))) return { error: 'must be an integer' };
  const value = Number(raw);
  if (value < min || value > max) return { error: 'must be between ' + min + ' and ' + max };
  return { value };
}

function listProducts(query, store) {
  const limit = parseIntParam(query.limit, 20, 1, 100);
  const offset = parseIntParam(query.offset, 0, 0, Number.MAX_SAFE_INTEGER);
  const details = [];
  if (limit.error) details.push({ field: 'limit', message: 'limit ' + limit.error });
  if (offset.error) details.push({ field: 'offset', message: 'offset ' + offset.error });
  if (details.length) {
    return { status: 400, body: { error: { code: 'VALIDATION_ERROR', message: 'Invalid query parameters', details } } };
  }
  const items = store.all();
  const data = items.slice(offset.value, offset.value + limit.value);
  return { status: 200, body: { data, meta: { total: items.length, limit: limit.value, offset: offset.value,
    hasMore: offset.value + data.length < items.length } } };
}

module.exports = { listProducts };

