'use strict';

const defaultSleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const isRetryable = err => Boolean(err) && (err.retryable === true || err.status === 429
  || (typeof err.status === 'number' && err.status >= 500));

async function withRetry(fn, options = {}) {
  const { retries = 3, baseDelayMs = 100, maxDelayMs = 2000, sleep = defaultSleep } = options;
  for (let attempt = 1; ; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      if (!isRetryable(err) || attempt > retries) throw err;
      await sleep(Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs));
    }
  }
}

module.exports = { withRetry, isRetryable };

