'use strict';

class ConfigError extends Error {
  constructor(code, message, options = {}) {
    super(message, options.cause ? { cause: options.cause } : undefined);
    this.name = 'ConfigError';
    this.code = code;
    if (options.field) this.field = options.field;
  }
}

function loadConfig(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (cause) {
    throw new ConfigError('CONFIG_PARSE', 'Config is not valid JSON: ' + cause.message, { cause });
  }
  if (!raw || typeof raw !== 'object') throw new ConfigError('CONFIG_INVALID', 'Config must be a JSON object');
  for (const field of ['apiUrl', 'timeoutMs']) {
    if (raw[field] === undefined) throw new ConfigError('CONFIG_MISSING', 'Missing required field: ' + field, { field });
  }
  if (!Number.isInteger(raw.timeoutMs) || raw.timeoutMs <= 0) {
    throw new ConfigError('CONFIG_INVALID', 'timeoutMs must be a positive integer', { field: 'timeoutMs' });
  }
  return { apiUrl: raw.apiUrl, timeoutMs: raw.timeoutMs, retries: raw.retries === undefined ? 2 : raw.retries };
}

module.exports = { loadConfig, ConfigError };

