'use strict';

const LINE = /^(\S+) \S+ (\S+) \[([^\]]+)\] "([A-Z]+) (\S+) (HTTP\/[0-9.]+)" (\d{3}) (\d+|-)(?: "([^"]*)" "([^"]*)")?$/;
const dash = value => (value === undefined || value === '-' ? null : value);

function parseLine(line) {
  const m = LINE.exec(line);
  if (!m) return null;
  return { ip: m[1], user: dash(m[2]), time: m[3], method: m[4], path: m[5], protocol: m[6],
    status: Number(m[7]), bytes: m[8] === '-' ? 0 : Number(m[8]), referrer: dash(m[9]), userAgent: dash(m[10]) };
}

function parseLog(text) {
  const entries = [];
  let invalid = 0;
  for (const line of String(text).split(/\r?\n/)) {
    if (!line.trim()) continue;
    const entry = parseLine(line);
    if (entry) entries.push(entry); else invalid++;
  }
  return { entries, invalid };
}

module.exports = { parseLine, parseLog };

