'use strict';

const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september',
  'october', 'november', 'december'];
const pad = n => String(n).padStart(2, '0');

function parseDate(value) {
  let m = /^(\d{4})-(\d{2})-(\d{2})\b/.exec(value);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})\b/.exec(value);
  if (m) return m[3] + '-' + pad(m[2]) + '-' + pad(m[1]);
  m = /^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})\b/.exec(value);
  if (m && MONTHS.includes(m[2].toLowerCase())) return m[3] + '-' + pad(MONTHS.indexOf(m[2].toLowerCase()) + 1) + '-' + pad(m[1]);
  return null;
}

function parseAmount(value) {
  const m = /^(?:(\$)|([A-Z]{3})\s+)?([\d,]+(?:\.\d+)?)(?:\s+([A-Z]{3}))?\s*$/.exec(value.trim());
  if (!m) return null;
  const currency = m[1] ? 'USD' : m[2] || m[4] || null;
  return { total: Number(m[3].replace(/,/g, '')), currency };
}

function extractInvoice(text) {
  const out = { invoiceNumber: null, date: null, total: null, currency: null };
  for (const line of String(text).split(/\r?\n/)) {
    let m;
    if (!out.invoiceNumber && (m = /^\s*invoice\s*(?:#|no\.?|number)\s*:?\s*([A-Za-z0-9-]+)\s*$/i.exec(line))) out.invoiceNumber = m[1];
    else if (!out.date && (m = /^\s*(?:invoice\s+date|date|issued)\s*:\s*(.+)$/i.exec(line))) out.date = parseDate(m[1].trim());
    else if (out.total === null && (m = /^\s*(?:total(?:\s+due)?|amount\s+due)\s*:\s*(.+)$/i.exec(line))) {
      const amount = parseAmount(m[1]);
      if (amount) { out.total = amount.total; out.currency = amount.currency; }
    }
  }
  return out;
}

module.exports = { extractInvoice };

