function encodeCursor(row) {
  return Buffer.from(JSON.stringify({ c: row.created_at, i: row.id })).toString('base64url');
}

function decodeCursor(cursor) {
  let value;
  try { value = JSON.parse(Buffer.from(String(cursor), 'base64url').toString('utf8')); } catch { value = null; }
  if (!value || typeof value.c !== 'string' || Number.isNaN(Date.parse(value.c))
    || !(Number.isSafeInteger(value.i) || /^\d+$/.test(String(value.i)))) throw new Error('Malformed cursor');
