  if (!Number.isInteger(limit) || limit < 1 || limit > 50) throw new RangeError('limit must be an integer 1..50');
  if (cursor === undefined || cursor === null) {
    return { text: COLUMNS + ' WHERE user_id = $1 ORDER BY created_at DESC, id DESC LIMIT $2', values: [userId, limit] };
  }
  const { c, i } = decodeCursor(cursor);
  return { text: COLUMNS + ' WHERE user_id = $1 AND (created_at, id) < ($2, $3) ORDER BY created_at DESC, id DESC LIMIT $4',
