async function syncStock(db, items) {
  const latest = new Map();
  for (const item of items) { latest.delete(item.sku); latest.set(item.sku, item.quantity); }
  if (latest.size === 0) return 0;
  const values = [];
  const rows = [];
  for (const [sku, quantity] of latest) {
    values.push(sku, quantity);
    rows.push('($' + (values.length - 1) + ', $' + values.length + ', now())');
  }
  await db.query('INSERT INTO inventory (sku, quantity, updated_at) VALUES ' + rows.join(', ')
    + ' ON CONFLICT (sku) DO UPDATE SET quantity = EXCLUDED.quantity, updated_at = now()', values);
  return latest.size;
}

