'use strict';
const crypto = require('node:crypto');

const cacheKeyFor = buffer => crypto.createHash('sha256').update(buffer).digest('hex');

function createExtractor({ readFile, parse }) {
  const cache = new Map();
  let hits = 0;
  let misses = 0;
  return {
    extract(filePath) {
      const bytes = readFile(filePath);
      const key = cacheKeyFor(bytes);
      if (cache.has(key)) {
        hits++;
        return cache.get(key);
      }
      misses++;
      const result = parse(bytes.toString('utf8'));
      cache.set(key, result);
      return result;
    },
    stats: () => ({ hits, misses }),
  };
}

module.exports = { createExtractor, cacheKeyFor };

