'use strict';

const ROLE_PERMISSIONS = {
  admin: ['read', 'write', 'delete'],
  editor: ['read', 'write'],
  viewer: ['read'],
};

const KNOWN = new Set(Object.values(ROLE_PERMISSIONS).flat());

function requirePermission(permission) {
  if (!KNOWN.has(permission)) throw new Error('Unknown permission: ' + permission);
  return (req, res, next) => {
    if (!req.user) return res.status(401).json({ error: { code: 'UNAUTHENTICATED', message: 'Authentication required' } });
    const role = req.user.role;
    const granted = typeof role === 'string' && Object.prototype.hasOwnProperty.call(ROLE_PERMISSIONS, role)
      ? ROLE_PERMISSIONS[role] : [];
    if (!granted.includes(permission)) {
      return res.status(403).json({ error: { code: 'FORBIDDEN', message: 'Missing permission: ' + permission } });
    }
    return next();
  };
}

module.exports = { requirePermission, ROLE_PERMISSIONS };

