function addItem(cart, item) {
  const exists = cart.items.some(i => i.sku === item.sku);
  const items = exists
    ? cart.items.map(i => (i.sku === item.sku ? { ...i, quantity: i.quantity + item.quantity } : i))
    : [...cart.items, { ...item }];
  return { ...cart, items };
}

function removeItem(cart, sku) {
  return { ...cart, items: cart.items.filter(i => i.sku !== sku) };
}

function applyDiscount(cart, pct) {
  if (typeof pct !== 'number' || !(pct >= 0 && pct <= 100)) throw new RangeError('pct must be between 0 and 100');
  return { ...cart, discountPct: pct };
}

function total(cart) {
  const sum = cart.items.reduce((acc, i) => acc + i.price * i.quantity, 0);
  return Math.round(sum * (1 - (cart.discountPct || 0) / 100) * 100) / 100;
}

module.exports = { addItem, removeItem, applyDiscount, total };

