function createUserCache({ redis, db, ttlSeconds = 300 }) {
  const key = id => 'user:' + id;
  const quietly = async op => { try { return await op(); } catch { return null; } };
  return {
    async getUser(id) {
      const cached = await quietly(() => redis.get(key(id)));
      if (cached) {
        try { return JSON.parse(cached); } catch { /* fall through to db */ }
      }
      const user = await db.findUser(id);
      if (user) await quietly(() => redis.set(key(id), JSON.stringify(user), { EX: ttlSeconds }));
      return user || null;
    },
    async updateUser(id, patch) {
      const updated = await db.updateUser(id, patch);
      await quietly(() => redis.del(key(id)));
      return updated;
    },
  };
}

module.exports = { createUserCache };

