'use strict';

const assertDecimals = d => { if (!Number.isInteger(d) || d < 0 || d > 255) throw new RangeError('decimals must be 0..255'); };

function formatUnits(raw, decimals) {
  assertDecimals(decimals);
  let value = BigInt(raw);
  const negative = value < 0n;
  if (negative) value = -value;
  const base = 10n ** BigInt(decimals);
  const whole = value / base;
  const fraction = (value % base).toString().padStart(decimals, '0').replace(/0+$/, '');
  return (negative ? '-' : '') + whole.toString() + (fraction ? '.' + fraction : '');
}

function parseUnits(value, decimals) {
  assertDecimals(decimals);
  const m = /^(-)?(\d+)(?:\.(\d+))?$/.exec(String(value));
  if (!m) throw new Error('Invalid decimal amount: ' + value);
  const fraction = m[3] || '';
  if (fraction.length > decimals) throw new RangeError('Too many fractional digits for ' + decimals + ' decimals');
  const units = BigInt(m[2] + fraction.padEnd(decimals, '0'));
  return m[1] ? -units : units;
}

function normalizeAmount(raw, fromDecimals, toDecimals) {
  assertDecimals(fromDecimals);
  assertDecimals(toDecimals);
  const value = BigInt(raw);
  if (toDecimals >= fromDecimals) return value * 10n ** BigInt(toDecimals - fromDecimals);
  return value / 10n ** BigInt(fromDecimals - toDecimals);
}

module.exports = { formatUnits, parseUnits, normalizeAmount };

